import 'package:flutter/material.dart';import 'package:model_viewer_plus/model_viewer_plus.dart';class Screen3D extends StatelessWidget {  final String? url;  const Screen3D({super.key, required this.url});  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(title: const Text('Model Viewer')),      body: ModelViewer(        src: url ?? 'https://raw.githubusercontent.com/felopatersameh/Models3DCreator/main/tripo_pbr_model_18f50e08-3c6b-4ea6-831f-476e0b43f4f0.glb',        alt: 'A 3D model ',        ar: true,        // AR support        arModes: ['scene-viewer', 'webxr', 'quick-look'],        // أوضاع AR        cameraControls: true,        // Allow the user to rotate and move the camera        disableZoom: false,        // Allow zooming and miniaturization        autoRotate: true,        //Rotate the form automatically        rotationPerSecond: "30deg",        // Spinning        cameraOrbit: "0deg 75deg 2.5m",        //Camera settings        shadowIntensity: 1.0,        // The severity of the shadows        shadowSoftness: 0.5,        //The softness of shades        exposure: 1.5, // Improving lighting      ),    );  }}